const b = $input.first().json.body ?? $input.first().json;
const opsLeadName = b.opsLeadName || 'the Ops Lead';

const prompt = `Write a short, friendly Slack-style nudge (2-3 sentences max) to ${opsLeadName}, the onboarding Ops Lead at a physiotherapy clinic. ${b.employeeName} (${b.title} at ${b.location}) has ${b.missingDocCount} outstanding onboarding document(s). Ask ${opsLeadName} to follow up with ${b.employeeName} directly. Do not use markdown formatting.`;

return [{ json: { ...b, prompt } }];
